def transform(grid):
    g=[row[:] for row in grid]
    from collections import Counter
    counts=Counter(v for row in g for v in row if v != 0)
    if not counts:
        return g
    common=counts.most_common(1)[0][0]
    h=len(g); w=len(g[0])
    for color in counts:
        if color == common:
            continue
        # Extend matching interior marks across blank gaps on each row and column.
        for y in range(h):
            xs=[x for x in range(w) if g[y][x]==color]
            for a,b in zip(xs,xs[1:]):
                for x in range(a+1,b):
                    if g[y][x]==0: g[y][x]=color
        for x in range(w):
            ys=[y for y in range(h) if g[y][x]==color]
            for a,b in zip(ys,ys[1:]):
                for y in range(a+1,b):
                    if g[y][x]==0: g[y][x]=color
    return g
